import json,re
path = "logs/backend.jsonl"
events = [json.loads(l) for l in open(path)]
paso2 = events[174:252]  # inclusive start, exclusive after paso_fin? line 251 is paso_fin
# actually 174 is paso_inicio, 251 is paso_fin; CLI is 175-250
print("paso2 tipos", [e['tipo'] for e in paso2[:3]], '... last', paso2[-1]['tipo'])

cmds=[]
file_changes=[]
for e in events[174:252]:
    if e['tipo']!='evento_cli': continue
    item=(e.get('payload') or {}).get('item') or {}
    if item.get('type')=='command_execution' and e.get('tipo_cli')=='item.completed':
        cmds.append((item.get('command'), item.get('exit_code'), (item.get('aggregated_output') or '')[:200]))
    if item.get('type')=='file_change':
        file_changes.append((e.get('tipo_cli'), item))

print('\n=== FILE CHANGES ===')
for t,it in file_changes:
    print(t, json.dumps(it, ensure_ascii=False)[:500])

print('\n=== COMMANDS COMPLETED ===')
for i,(c,ex,out) in enumerate(cmds,1):
    print(f"{i:02d} exit={ex} {c[:300]}")
    if any(x in (c or '') for x in ['npm','tsc','vitest','test','build','node dist','curl','npx']):
        print('   ** EXEC-LIKE ** out=', out.replace('\n',' | ')[:180])

print('\n=== writes to revision-backend? ===')
for i,(c,ex,out) in enumerate(cmds,1):
    if 'revision-backend' in (c or ''):
        print(i, c)
