    const appStateSubscription = AppState.addEventListener("change", (nextState) => {
      if (nextState === "active") {
        foreground = true;
        if (!authenticationFailed) connect();
        return;
      }
      foreground = false;
      clearRetry();
      setStatus("disconnected");
      const current = socket;
      socket = null;
      current?.close();
    });

    if (foreground) connect();

    return () => {
      disposed = true;
      foreground = false;
      clearRetry();
      appStateSubscription.remove();
      const current = socket;
      socket = null;
      current?.close();
    };
  }, [onUnauthenticated, token]);

