import * as Clipboard from "expo-clipboard";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import QRCode from "react-native-qrcode-svg";
import { ApiClientError, getDepositAddress } from "../api/client";
import type { Asset, DepositAddressResponse } from "../api/types";
import { useAuth } from "../session/AuthContext";
import { type SocketStatus, usePrivateSocket } from "../session/usePrivateSocket";

export function depositQrValue(deposit: DepositAddressResponse): string {
  if (deposit.asset === "ETH") return `ethereum:${deposit.address}@11155111`;
  if (!deposit.tokenAddress) throw new Error("La respuesta USDC requiere tokenAddress");
  return `ethereum:${deposit.tokenAddress}@11155111/transfer?address=${deposit.address}`;
}

const SOCKET_LABELS: Record<SocketStatus, string> = {
  connecting: "Conectando",
  live: "En vivo",
  reconnecting: "Reconectando",
  disconnected: "Desconectado",
};

export function DepositScreen() {
  const { token, logout, handleUnauthenticated } = useAuth();
  if (!token) throw new Error("DepositScreen requiere una sesión autenticada");
  const socketStatus = usePrivateSocket({ token, onUnauthenticated: handleUnauthenticated });
  const [asset, setAsset] = useState<Asset>("ETH");
  const [deposit, setDeposit] = useState<DepositAddressResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    setCopied(false);
    try {
      const response = await getDepositAddress(asset, token, handleUnauthenticated);
      setDeposit(response);
    } catch (caught) {
      setDeposit(null);
      if (caught instanceof ApiClientError && caught.code === "UNAUTHENTICATED") return;
      if (caught instanceof ApiClientError) {
        setError(caught.message || "No pudimos obtener la dirección de depósito.");
      } else {
        setError("Sin conexión con el exchange. Revisá tu red y reintentá.");
      }
    } finally {
      setLoading(false);
    }
  }, [asset, handleUnauthenticated, token]);

  useEffect(() => {
    void load();
  }, [load]);

  const copy = async () => {
    if (!deposit) return;
    await Clipboard.setStringAsync(deposit.address);
    setCopied(true);
  };

  return (
    <ScrollView contentContainerStyle={styles.content} style={styles.root}>
      <View style={styles.topbar}>
        <View>
          <Text style={styles.eyebrow}>FONDOS</Text>
          <Text style={styles.title}>Depositar</Text>
        </View>
        <Pressable accessibilityRole="button" onPress={() => { void logout(); }} style={styles.logout}>
          <Text style={styles.logoutText}>Salir</Text>
        </Pressable>
      </View>

      <View style={styles.networkRow}>
        <View style={[styles.statusDot, socketStatus === "live" && styles.statusLive]} />
        <Text style={styles.networkText}>Sesión {SOCKET_LABELS[socketStatus].toLowerCase()}</Text>
      </View>

      <Text style={styles.label}>Activo</Text>
      <View style={styles.segment}>
        {(["ETH", "USDC"] as const).map((candidate) => (
          <Pressable
            accessibilityRole="button"
            key={candidate}
            onPress={() => setAsset(candidate)}
            style={[styles.segmentButton, asset === candidate && styles.segmentActive]}
          >
            <Text style={[styles.segmentText, asset === candidate && styles.segmentTextActive]}>
              {candidate === "USDC" ? "USDC-mock" : "ETH"}
            </Text>
          </Pressable>
        ))}
      </View>

      <View style={styles.card}>
        <View style={styles.chainBadge}>
          <Text style={styles.chainBadgeText}>SEPOLIA · CHAIN ID 11155111</Text>
        </View>
        {loading ? (
          <View style={styles.centerState}>
            <ActivityIndicator color="#46d7b0" size="large" />
            <Text style={styles.muted}>Obteniendo tu dirección…</Text>
          </View>
        ) : error ? (
          <View style={styles.centerState}>
            <Text accessibilityRole="alert" style={styles.error}>{error}</Text>
            <Pressable accessibilityRole="button" onPress={() => { void load(); }} style={styles.retry}>
              <Text style={styles.retryText}>Reintentar</Text>
            </Pressable>
          </View>
        ) : deposit ? (
          <>
            <Text style={styles.instruction}>
              Enviá únicamente {deposit.asset === "USDC" ? "USDC-mock" : "ETH"} por la red Sepolia.
            </Text>
            <View style={styles.qrFrame} testID="deposit-qr">
              <QRCode
                backgroundColor="#ffffff"
                color="#07111f"
                quietZone={8}
                size={210}
                value={depositQrValue(deposit)}
              />
            </View>
            <Text style={styles.addressLabel}>Tu dirección de depósito</Text>
            <Text selectable style={styles.address} testID="deposit-address">{deposit.address}</Text>
            <Pressable accessibilityRole="button" onPress={() => { void copy(); }} style={styles.copyButton}>
              <Text style={styles.copyButtonText}>{copied ? "Dirección copiada" : "Copiar dirección"}</Text>
            </Pressable>
            <Text style={styles.note}>
              ETH y USDC-mock llegan a esta misma dirección. El QR ya incluye la red y el activo elegidos.
            </Text>
          </>
        ) : null}
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  root: { backgroundColor: "#07111f", flex: 1 },
  content: { paddingBottom: 40, paddingHorizontal: 20, paddingTop: 58 },
  topbar: { alignItems: "center", flexDirection: "row", justifyContent: "space-between", marginBottom: 14 },
  eyebrow: { color: "#46d7b0", fontSize: 11, fontWeight: "800", letterSpacing: 2 },
  title: { color: "#f4f8fc", fontSize: 34, fontWeight: "800", letterSpacing: -1, marginTop: 2 },
  logout: { borderColor: "#31455f", borderRadius: 10, borderWidth: 1, paddingHorizontal: 14, paddingVertical: 9 },
