  networkRow: { alignItems: "center", flexDirection: "row", marginBottom: 26 },
  statusDot: { backgroundColor: "#d49a53", borderRadius: 5, height: 8, marginRight: 7, width: 8 },
  statusLive: { backgroundColor: "#46d7b0" },
  networkText: { color: "#8495ab", fontSize: 12 },
  label: { color: "#aab9cc", fontSize: 13, fontWeight: "700", marginBottom: 8 },
  segment: { backgroundColor: "#0d1929", borderRadius: 13, flexDirection: "row", marginBottom: 18, padding: 4 },
  segmentButton: { alignItems: "center", borderRadius: 10, flex: 1, paddingVertical: 11 },
  segmentActive: { backgroundColor: "#25384e" },
  segmentText: { color: "#74859b", fontSize: 14, fontWeight: "700" },
  segmentTextActive: { color: "#f4f8fc" },
  card: { alignItems: "center", backgroundColor: "#101d2e", borderColor: "#21334b", borderRadius: 22, borderWidth: 1, minHeight: 500, padding: 20 },
  chainBadge: { alignSelf: "flex-start", backgroundColor: "#142b2c", borderRadius: 20, paddingHorizontal: 11, paddingVertical: 7 },
  chainBadgeText: { color: "#66dfbd", fontSize: 10, fontWeight: "800", letterSpacing: 1 },
  centerState: { alignItems: "center", flex: 1, justifyContent: "center", minHeight: 390 },
  muted: { color: "#8293a9", marginTop: 14 },
  error: { color: "#ffabab", lineHeight: 21, textAlign: "center" },
  retry: { backgroundColor: "#46d7b0", borderRadius: 11, marginTop: 18, paddingHorizontal: 20, paddingVertical: 11 },
  retryText: { color: "#041018", fontWeight: "800" },
  instruction: { color: "#c3cede", fontSize: 15, lineHeight: 22, marginBottom: 18, marginTop: 23, textAlign: "center" },
  qrFrame: { backgroundColor: "#ffffff", borderRadius: 18, padding: 10 },
  addressLabel: { alignSelf: "flex-start", color: "#8394aa", fontSize: 12, marginTop: 22 },
  address: { alignSelf: "stretch", color: "#f4f8fc", fontFamily: Platform.select({ ios: "Menlo", android: "monospace" }), fontSize: 14, lineHeight: 21, marginTop: 7, textAlign: "center" },
  copyButton: { alignItems: "center", alignSelf: "stretch", backgroundColor: "#46d7b0", borderRadius: 12, marginTop: 17, paddingVertical: 13 },
  copyButtonText: { color: "#041018", fontSize: 15, fontWeight: "800" },
  note: { color: "#788aa1", fontSize: 12, lineHeight: 18, marginTop: 16, textAlign: "center" },
});

