import { useRef, useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { ApiClientError } from "../api/client";
import { useAuth } from "../session/AuthContext";

const EMAIL_PATTERN = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;

function localValidation(email: string, password: string): string | null {
  if (email.trim().length === 0) return "Ingresá tu email.";
  if (!EMAIL_PATTERN.test(email.trim())) return "Ingresá un email válido.";
  if (password.length === 0) return "Ingresá tu contraseña.";
  return null;
}

export function LoginScreen() {
  const { login } = useAuth();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const submittingRef = useRef(false);

  const submit = async () => {
    if (submittingRef.current) return;
    const validation = localValidation(email, password);
    if (validation) {
      setError(validation);
      return;
    }

    submittingRef.current = true;
    setSubmitting(true);
    setError(null);
    const passwordInTransit = password;
    try {
      await login(email, passwordInTransit);
      setPassword("");
    } catch (caught) {
      if (caught instanceof ApiClientError && caught.code === "INVALID_CREDENTIALS") {
        setError("Email o contraseña incorrectos.");
      } else if (caught instanceof ApiClientError && caught.code === "RATE_LIMITED") {
        const seconds = caught.details?.retryAfterSeconds;
        setError(typeof seconds === "number"
          ? `Demasiados intentos. Reintentá en ${seconds} segundos.`
          : "Demasiados intentos. Reintentá más tarde.");
      } else if (caught instanceof ApiClientError) {
        setError("No pudimos iniciar sesión. Reintentá.");
      } else {
        setError("Sin conexión con el exchange. Revisá tu red y reintentá.");
      }
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === "ios" ? "padding" : undefined}
      style={styles.root}
    >
      <View style={styles.hero}>
        <Text style={styles.eyebrow}>SEPOLIA EXCHANGE</Text>
        <Text style={styles.title}>Tu acceso al mercado, sin ruido.</Text>
        <Text style={styles.subtitle}>Ingresá para consultar tu dirección de depósito segura.</Text>
      </View>

      <View style={styles.card}>
        <Text style={styles.cardTitle}>Iniciar sesión</Text>
        <Text style={styles.label}>Email</Text>
        <TextInput
          accessibilityLabel="Email"
          autoCapitalize="none"
          autoComplete="email"
          editable={!submitting}
          keyboardType="email-address"
          onChangeText={(value) => { setEmail(value); setError(null); }}
          placeholder="trader@example.com"
          placeholderTextColor="#617087"
          returnKeyType="next"
          style={styles.input}
          value={email}
        />
        <Text style={styles.label}>Contraseña</Text>
        <TextInput
          accessibilityLabel="Contraseña"
          autoCapitalize="none"
          autoComplete="current-password"
          editable={!submitting}
          onChangeText={(value) => { setPassword(value); setError(null); }}
          onSubmitEditing={() => { void submit(); }}
          placeholder="••••••••"
          placeholderTextColor="#617087"
          returnKeyType="go"
          secureTextEntry
          style={styles.input}
          value={password}
        />
        {error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}
        <Pressable
          accessibilityRole="button"
          disabled={submitting}
          onPress={() => { void submit(); }}
          style={({ pressed }) => [styles.button, pressed && styles.buttonPressed, submitting && styles.disabled]}
        >
          {submitting
            ? <ActivityIndicator color="#041018" />
            : <Text style={styles.buttonText}>Ingresar</Text>}
        </Pressable>
      </View>
      <Text style={styles.security}>La sesión se guarda únicamente en el almacén cifrado del dispositivo.</Text>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  root: { backgroundColor: "#07111f", flex: 1, justifyContent: "center", padding: 24 },
  hero: { marginBottom: 28 },
  eyebrow: { color: "#46d7b0", fontSize: 12, fontWeight: "800", letterSpacing: 2.2, marginBottom: 12 },
  title: { color: "#f4f8fc", fontSize: 36, fontWeight: "800", letterSpacing: -1.2, lineHeight: 41 },
  subtitle: { color: "#91a2ba", fontSize: 16, lineHeight: 23, marginTop: 12 },
  card: { backgroundColor: "#101d2e", borderColor: "#21334b", borderRadius: 22, borderWidth: 1, padding: 20 },
  cardTitle: { color: "#f4f8fc", fontSize: 22, fontWeight: "700", marginBottom: 20 },
  label: { color: "#b6c4d7", fontSize: 13, fontWeight: "600", marginBottom: 7 },
  input: { backgroundColor: "#091524", borderColor: "#2a3d57", borderRadius: 12, borderWidth: 1, color: "#f4f8fc", fontSize: 16, marginBottom: 16, paddingHorizontal: 14, paddingVertical: 13 },
  error: { color: "#ff9e9e", fontSize: 14, lineHeight: 20, marginBottom: 13 },
  button: { alignItems: "center", backgroundColor: "#46d7b0", borderRadius: 12, height: 50, justifyContent: "center", marginTop: 3 },
  buttonPressed: { opacity: 0.85 },
  buttonText: { color: "#041018", fontSize: 16, fontWeight: "800" },
  disabled: { opacity: 0.65 },
  security: { color: "#718299", fontSize: 12, lineHeight: 17, marginTop: 18, textAlign: "center" },
});

