import { expireSession, type Session } from "./session";

interface ErrorEnvelope {
  error?: {
    code?: unknown;
    details?: unknown;
  };
}

export interface LoginResponse extends Session {}

export interface ProfileResponse {
  accountId: string;
  email: string;
  status: "ACTIVE";
  createdAt: string;
}

export class ApiResponseError extends Error {
  constructor(
    readonly code: string,
    readonly status: number,
    readonly details?: unknown,
  ) {
    super(code);
    this.name = "ApiResponseError";
  }
}

export class NetworkError extends Error {
  constructor() {
    super("NETWORK_ERROR");
    this.name = "NetworkError";
  }
}

const configuredBaseUrl = import.meta.env.VITE_API_BASE_URL?.trim();
export const API_BASE_URL = (configuredBaseUrl || "http://127.0.0.1:3000/api/v1").replace(/\/+$/, "");

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

async function requestJson<T>(path: string, init: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${API_BASE_URL}${path}`, init);
  } catch {
    throw new NetworkError();
  }

  let body: unknown;
  try {
    body = await response.json();
  } catch {
    throw new NetworkError();
  }

  if (!response.ok) {
    const envelope = body as ErrorEnvelope;
    const code = envelope.error?.code;
    if (typeof code === "string") {
      throw new ApiResponseError(code, response.status, envelope.error?.details);
    }
    throw new NetworkError();
  }
  return body as T;
}

export async function login(email: string, password: string): Promise<LoginResponse> {
  const result = await requestJson<unknown>("/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!isRecord(result) || typeof result.token !== "string" || result.token.length === 0
    || typeof result.expiresAt !== "string" || !Number.isFinite(Date.parse(result.expiresAt))) {
    throw new NetworkError();
  }
  return { token: result.token, expiresAt: result.expiresAt };

