import json
# expo-doctor output
events=[]
with open('logs/mobile.jsonl') as f:
    for i,line in enumerate(f):
        events.append((i, json.loads(line)))
# paso2 194-345
for i,o in events[194:346]:
    if o['tipo']!='evento_cli': continue
    item=(o.get('payload') or {}).get('item') or {}
    if item.get('type')=='command_execution' and o.get('tipo_cli')=='item.completed':
        cmd=item.get('command') or ''
        if 'expo-doctor' in cmd or 'newArch' in cmd:
            print('CMD', cmd[:400])
            print('EXIT', item.get('exit_code'))
            print('OUT:')
            print(item.get('aggregated_output'))
            print('---')

# file_change all events
print('\nALL file_change in mobile paso2:')
for i,o in events[194:346]:
    item=(o.get('payload') or {}).get('item') or {}
